			writeRaw(t, file, marker)
			requireCapacityRejection(t, SaveModelPackage(context.Background(), file, corrupt))
			bundle := t.TempDir()
			bundleMarker := filepath.Join(bundle, "marker.txt")
			writeRaw(t, bundleMarker, marker)
			requireCapacityRejection(t, SaveModelPackageBundle(context.Background(), bundle, corrupt))
