				got, err := os.ReadFile(path)
				if err != nil || !bytes.Equal(got, marker) {
					t.Fatalf("rejected save changed existing data at %s: %v", path, err)
				}
			}
			if !bytes.Equal(before, mustJSON(t, corrupt)) {
				t.Fatal("rejected save changed the caller's package")
			}
		})
	}
